#!/usr/bin/env node
/**
 * tests/adversarial-m4-stress.js - Empirical Adversarial Stress Suite for Milestone 4
 * 
 * Challenger Agent: challenger_m4_2
 * Role: Empirical Challenger (Critic & Specialist)
 * Target: View Controllers, Virtual Keyboard, Focus Trapping, Network Races, Dynamic DOM
 */

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// 2. Terminal Colors
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(category, testName, fn) {
  totalChecks++;
  const idStr = totalChecks.toString().padStart(2, '0');
  const label = `[ADV-M4-${idStr}] [${category}] ${testName}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.red}Error: ${err.message}${C.reset}`);
  }
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

// 3. Layout and Scroll Mocks (1080p canvas)
function installScrollMocks(window) {
  window.Element.prototype.scrollIntoView = function (options) {
    this._lastScrollIntoView = options || true;
  };

  window.Element.prototype.scrollTo = function (x, y) {
    if (typeof x === 'object') {
      this.scrollLeft = x.left !== undefined ? x.left : (this.scrollLeft || 0);
      this.scrollTop = x.top !== undefined ? x.top : (this.scrollTop || 0);
      this._lastScrollBehavior = x.behavior || 'auto';
    } else {
      this.scrollLeft = x !== undefined ? x : (this.scrollLeft || 0);
      this.scrollTop = y !== undefined ? y : (this.scrollTop || 0);
    }
  };
}

function installLayoutMock(window) {
  function makeRect(left, top, width, height) {
    return {
      left: left,
      top: top,
      width: width,
      height: height,
      right: left + width,
      bottom: top + height,
      x: left,
      y: top
    };
  }

  window.Element.prototype.getBoundingClientRect = function () {
    var mockAttr = this.getAttribute('data-mock-rect');
    if (mockAttr) {
      try {
        var parsed = JSON.parse(mockAttr);
        return makeRect(parsed.left || 0, parsed.top || 0, parsed.width || 0, parsed.height || 0);
      } catch (err) {}
    }

    if (this.style.display === 'none') return makeRect(0, 0, 0, 0);

    // Header and Nav Pills
    if (this.classList.contains('brand-container')) return makeRect(96, 24, 200, 48);
    if (this.classList.contains('nav-pill-item')) {
      var route = this.getAttribute('data-route');
      if (route === 'home') return makeRect(790, 28, 75, 40);
      if (route === 'movies') return makeRect(875, 28, 85, 40);
      if (route === 'series') return makeRect(970, 28, 80, 40);
      if (route === 'search') return makeRect(1060, 28, 80, 40);
    }

    // Hero Actions
    if (this.id === 'hero-play-btn') return makeRect(96, 460, 180, 56);
    if (this.id === 'hero-details-btn') return makeRect(292, 460, 140, 56);
    if (this.id === 'hero-list-btn') return makeRect(433, 460, 140, 56);

    // Details Actions
    if (this.id === 'details-play-btn') return makeRect(96, 450, 180, 56);
    if (this.id === 'player-back-btn') return makeRect(96, 54, 56, 56);

    // Content Shelves
    if (this.classList.contains('content-shelf')) {
      var parent = this.parentElement || document.body;
      var shelfIdx = Array.from(parent.children).indexOf(this);
      return makeRect(0, 560 + shelfIdx * 400, 1920, 380);
    }

    // Dynamic Poster Cards (2:3 aspect ratio)
    if (this.classList.contains('card-poster')) {
      var grid = this.closest('.content-grid-6col');
      if (grid) {
        var cardIdx = Array.from(this.parentElement.children).indexOf(this);
        var col = cardIdx % 6;
        var row = Math.floor(cardIdx / 6);
        return makeRect(96 + col * 288, 180 + row * 424, 264, 396);
      }
      var p = this.parentElement;
      var index = p ? Array.from(p.children).indexOf(this) : 0;
      var shelf = this.closest('.content-shelf');
      var sIdx = shelf && shelf.parentElement ? Array.from(shelf.parentElement.children).indexOf(shelf) : 1;
      var shelfTop = 560 + sIdx * 400 + 60;
      var rail = this.closest('.shelf-rail');
      var currentScroll = rail ? (rail.scrollLeft || 0) : 0;
      return makeRect(96 + index * 244 - currentScroll, shelfTop, 220, 330);
    }

    // Episode Cards (16:9 aspect ratio: 320x180)
    if (this.classList.contains('card-episode')) {
      var epIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      var epRail = this.closest('.shelf-rail');
      var epScroll = epRail ? (epRail.scrollLeft || 0) : 0;
      return makeRect(96 + epIndex * 344 - epScroll, 670, 320, 180);
    }

    // Filter pills & Season tabs
    if (this.classList.contains('filter-pill') || this.classList.contains('season-pill') || this.classList.contains('season-tab-btn')) {
      var pillIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      return makeRect(96 + pillIndex * 130, 110, 110, 44);
    }

    // Cast Cards
    if (this.classList.contains('cast-item')) {
      var cIndex = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      var cRail = this.closest('.shelf-rail');
      var cScroll = cRail ? (cRail.scrollLeft || 0) : 0;
      return makeRect(96 + cIndex * 120 - cScroll, 600, 110, 150);
    }

    // Keyboard buttons
    if (this.classList.contains('key-btn')) {
      var rowEl = this.closest('.keyboard-row');
      var rIdx = rowEl && rowEl.parentElement ? Array.from(rowEl.parentElement.children).indexOf(rowEl) : 0;
      var cIdx = rowEl ? Array.from(rowEl.children).indexOf(this) : 0;
      return makeRect(96 + cIdx * 60, 220 + rIdx * 60, 50, 50);
    }

    // Provider cards
    if (this.classList.contains('card-provider')) {
      var provIdx = this.parentElement ? Array.from(this.parentElement.children).indexOf(this) : 0;
      return makeRect(96 + provIdx * 120, 600, 100, 100);
    }

    return makeRect(96, 100, 100, 40);
  };
}

function generateMockCards(count, type, prefix) {
  var list = [];
  for (var i = 1; i <= count; i++) {
    list.push({
      id: 1000 + i,
      title: (prefix || 'Title') + ' ' + i,
      name: (prefix || 'Title') + ' ' + i,
      overview: 'Overview description for item ' + i,
      poster_path: '/poster_' + i + '.jpg',
      backdrop_path: '/backdrop_' + i + '.jpg',
      media_type: type,
      genre_ids: [28, 878],
      release_date: '2024-01-0' + (i % 9 + 1),
      first_air_date: '2024-01-0' + (i % 9 + 1),
      vote_average: 8.5,
      vote_count: 500 + i * 10,
      popularity: 100 + i
    });
  }
  return list;
}

var BASE_ROUTES = {
