  '/genre/movie/list': {
    genres: [{ id: 28, name: 'Action' }, { id: 878, name: 'Sci-Fi' }, { id: 18, name: 'Drama' }]
  },
  '/genre/tv/list': {
    genres: [{ id: 10759, name: 'Action & Adventure' }, { id: 18, name: 'Drama' }]
  },
  '/discover/movie': function (url) {
