    }
    return { page: 1, total_pages: 5, results: generateMockCards(20, 'tv', 'Discovered Show') };
  },
  '/tv/94997': {
    id: 94997, name: 'House of the Dragon', numberOfSeasons: 3,
    credits: {
      cast: [
        { id: 10, name: 'Matt Smith', character: 'Daemon Targaryen', profile_path: '/smith.jpg' },
        { id: 11, name: 'Emma D\'Arcy', character: 'Rhaenyra Targaryen', profile_path: '/darcy.jpg' }
      ]
    }
  },
