    id: 101, season_number: 1, name: 'Season 1',
    episodes: [
      { id: 1001, episode_number: 1, name: 'The Heirs of the Dragon', runtime: 66, still_path: '/ep1.jpg' },
      { id: 1002, episode_number: 2, name: 'The Rogue Prince', runtime: 54, still_path: '/ep2.jpg' }
    ]
  },
