    episodes: [
      { id: 2001, episode_number: 1, name: 'A Son for a Son', runtime: 61, still_path: '/ep2_1.jpg' },
      { id: 2002, episode_number: 2, name: 'Rhaenyra the Cruel', runtime: 69, still_path: '/ep2_2.jpg' },
