};

function createHarness(options) {
  var opts = options || {};
  var initialRoute = opts.initialRoute || 'home';
  var customRoutes = opts.mockRoutes || {};

  var projectRoot = path.resolve(__dirname, '..');
  var htmlPath = path.resolve(projectRoot, 'app/index.html');
  var configPath = path.resolve(projectRoot, 'app/js/config.js');
  var navPath = path.resolve(projectRoot, 'app/js/navigation.js');
  var tmdbPath = path.resolve(projectRoot, 'app/js/tmdb.js');
  var homePath = path.resolve(projectRoot, 'app/js/views/home.js');
  var catalogPath = path.resolve(projectRoot, 'app/js/views/catalog.js');
  var searchPath = path.resolve(projectRoot, 'app/js/views/search.js');
  var detailsPath = path.resolve(projectRoot, 'app/js/views/details.js');
  var appPath = path.resolve(projectRoot, 'app/js/app.js');

  var html = fs.readFileSync(htmlPath, 'utf8');
  var dom = new JSDOM(html, {
    url: 'http://localhost/#' + initialRoute,
    runScripts: 'outside-only'
  });
  var window = dom.window;

  installScrollMocks(window);
  installLayoutMock(window);

  var routes = Object.assign({}, BASE_ROUTES, customRoutes);
  window._fetchCalls = [];
  var sortedPatterns = Object.keys(routes).sort((a, b) => b.length - a.length);

  window.fetch = function (url, fetchOpts) {
    var urlStr = String(url);
    window._fetchCalls.push({ url: urlStr, options: fetchOpts || {} });

    for (var i = 0; i < sortedPatterns.length; i++) {
      var pat = sortedPatterns[i];
      if (urlStr.indexOf(pat) !== -1) {
        var h = routes[pat];
        var res = typeof h === 'function' ? h(urlStr, fetchOpts) : h;

        if (res && res._delayMs) {
          return new Promise(function (resolve) {
            setTimeout(function () {
              resolve({
                ok: !res._error,
                status: res._error ? 500 : 200,
                statusText: res._error ? 'Server Error' : 'OK',
                json: function () {
                  return res._error ? Promise.reject(new Error('Server Error')) : Promise.resolve(JSON.parse(JSON.stringify(res.data || res)));
                }
              });
            }, res._delayMs);
          });
        }

        if (res && res._error) {
          return Promise.resolve({
            ok: false,
            status: 500,
            statusText: 'Internal Error',
            json: function () { return Promise.reject(new Error('Internal Error')); }
          });
        }

        return Promise.resolve({
          ok: true,
          status: 200,
          statusText: 'OK',
          json: function () { return Promise.resolve(JSON.parse(JSON.stringify(res))); }
        });
      }
    }

    return Promise.resolve({
      ok: false,
      status: 404,
      statusText: 'Not Found',
      json: function () { return Promise.resolve({ error: true }); }
    });
  };

