  await check('SPATIAL', 'Catalog 6-Column Grid Traversal & Page 2 Pagination', async function () {
    var h = createHarness({ initialRoute: 'movies' });
    h.app.switchView('movies');
    await sleep(50);

    var grid = h.document.querySelector('#view-movies .content-grid-6col');
    var initialCards = grid.querySelectorAll('.card-poster');
    assert.strictEqual(initialCards.length, 20, 'Page 1 must render 20 cards');

    // Focus on (row 0, col 0)
    h.nav.setFocus(initialCards[0]);

    // Move RIGHT 5 times to (row 0, col 5)
    for (var r = 0; r < 5; r++) {
      h.nav.move('right');
    }
    assert.strictEqual(h.nav.getCurrentFocus(), initialCards[5], 'Must focus 6th card in row 0');

    // Move DOWN to row 1, col 5 (card 11)
    h.nav.move('down');
    assert.strictEqual(h.nav.getCurrentFocus(), initialCards[11], 'Must focus card 11 in row 1');

    // Focus on card 19 (bottom of page 1) and trigger pagination
    h.nav.setFocus(initialCards[19]);
    h.movies.loadCatalog(false); // fetch page 2
    await sleep(50);

    var totalCards = grid.querySelectorAll('.card-poster');
    assert.strictEqual(totalCards.length, 40, 'Grid must now contain 40 cards across pages 1 and 2');

    // Move DOWN or RIGHT to transition to new card 20
    h.nav.move('down');
    var nextFocus = h.nav.getCurrentFocus();
    assert(nextFocus && nextFocus.getAttribute('data-nav-index') === '20', 'Focus must seamlessly enter page 2 cards');
  });

  await check('SPATIAL', 'Details View Cast Rail Navigation', async function () {
    var h = createHarness({ initialRoute: 'details' });
    h.app.openDetails({ id: 693134, type: 'movie', title: 'Dune: Part Two' });
    await sleep(50);

    var castRail = h.document.getElementById('details-cast-rail');
    assert(castRail, 'Cast rail must exist');
    var castItems = castRail.querySelectorAll('.cast-item');
    assert(castItems.length > 0, 'Cast items must be rendered');

    h.nav.setFocus(castItems[0]);
    assert.strictEqual(h.nav.getCurrentFocus(), castItems[0]);
    assert.strictEqual(castItems[0].getAttribute('data-nav'), 'true');
    assert.strictEqual(castItems[0].getAttribute('data-nav-group'), 'details-cast');
  });

  // ===========================================================================
  // Summary & Report
  // ===========================================================================
  console.log(`\n${C.bold}========================================================================${C.reset}`);
  console.log(`${C.bold}Adversarial Stress Test Execution Summary:${C.reset}`);
  console.log(`  Total Checks:   ${totalChecks}`);
  console.log(`  Passed Checks:  ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red + failedChecks + C.reset : '0'}`);
  console.log(`${C.bold}========================================================================${C.reset}\n`);

  if (failedChecks === 0) {
    console.log(`${C.green}${C.bold}✅ ALL ${totalChecks} ADVERSARIAL STRESS CHECKS PASSED (100% SUCCESS)${C.reset}\n`);
    process.exit(0);
  } else {
    console.error(`${C.red}${C.bold}❌ ${failedChecks} ADVERSARIAL CHECKS FAILED${C.reset}\n`);
    failureList.forEach(function (f) {
      console.error(`- ${f.label}: ${f.error}`);
    });
    process.exit(1);
  }
}

runAdversarialM4Suite().catch(function (err) {
  console.error('Unhandled fatal error in adversarial test suite:', err);
  process.exit(1);
});

