h.app.switchView('search');

// 1. User types "SLOW"
h.search.query = 'SLOW';
h.search.scheduleSearch();

// Advance 320ms so SLOW request fires and is inflight (resolves at 320+600 = 920ms)
await sleep(320);

// 2. User quickly changes mind and types "FAST"
h.search.query = 'FAST';
h.search.scheduleSearch();

// Advance 340ms: FAST debounce fires (300ms) + FAST completes (20ms) -> FAST results rendered at ~660ms
await sleep(340);
var grid = h.document.getElementById('search-results-grid');
var currentTitle = grid.querySelector('.card-poster')?.getAttribute('data-title');
assert.strictEqual(currentTitle, 'NEW FAST MOVIE', 'FAST results must be displayed after fast request resolves');

// Advance 350ms: now at ~1010ms, SLOW request (which finished at ~920ms) has arrived!
await sleep(350);

// Vulnerability check: Did stale SLOW request overwrite FAST results?
var titleAfterStaleArrival = grid.querySelector('.card-poster')?.getAttribute('data-title');
assert.strictEqual(
  titleAfterStaleArrival,
  'NEW FAST MOVIE',
  `Stale inflight request must NOT overwrite newer search query results! Got: "${titleAfterStaleArrival}"`
);

