args.ReplacementContent:
await check('SPATIAL', 'Details View Cast Rail Navigation', async function () {
  var h = createHarness({ initialRoute: 'details' });
  h.app.openDetails({ id: 693134, type: 'movie', title: 'Dune: Part Two' });
  await sleep(50);

  var castRail = h.document.getElementById('details-cast-rail');
  assert(castRail, 'Cast rail must exist');
  var castItems = castRail.querySelectorAll('.cast-item');
  assert(castItems.length > 0, 'Cast items must be rendered');

  h.nav.setFocus(castItems[0]);
  assert.strictEqual(h.nav.getCurrentFocus(), castItems[0]);
  assert.strictEqual(castItems[0].getAttribute('data-nav'), 'true');
  assert.strictEqual(castItems[0].getAttribute('data-nav-group'), 'details-cast');
});

await check('CATALOG', 'Rapid Filter Switching: Click Second Genre While First Is Loading', async function () {
  var h = createHarness({
    initialRoute: 'movies',
    mockRoutes: {
      '/discover/movie': function (url) {
        if (url.indexOf('with_genres=28') !== -1) {
          return {
            _delayMs: 200, // Action is slow
            data: { page: 1, results: generateMockCards(10, 'movie', 'Action Movie') }
          };
        }
        if (url.indexOf('with_genres=878') !== -1) {
          return {
            _delayMs: 20, // Sci-Fi is fast
            data: { page: 1, results: generateMockCards(10, 'movie', 'Sci-Fi Movie') }
          };
        }
        return { page: 1, results: generateMockCards(10, 'movie', 'Default Movie') };
      }
    }
  });
  h.app.switchView('movies');
  await sleep(50);

  var filterBar = h.document.querySelector('#view-movies .filter-bar');
  var actionPill = filterBar.querySelector('.filter-pill[data-genre-id="28"]');
  var scifiPill = filterBar.querySelector('.filter-pill[data-genre-id="878"]');
  assert(actionPill && scifiPill, 'Pills exist');

  // Click Action pill (slow, takes 200ms)
  actionPill.click();
  assert.strictEqual(h.movies.state.isLoading, true, 'Catalog is loading');

  // At 20ms while Action is loading, click Sci-Fi pill
  await sleep(20);
  scifiPill.click();
  assert(scifiPill.classList.contains('active'), 'Sci-Fi pill is marked active');

  // Wait 300ms for all promises to resolve
  await sleep(300);

  // Verify grid content matches active Sci-Fi pill
  var grid = h.document.querySelector('#view-movies .content-grid-6col');
  var renderedTitle = grid.querySelector('.card-poster')?.getAttribute('data-title');
  assert(
    renderedTitle && renderedTitle.indexOf('Sci-Fi') !== -1,
    `When Sci-Fi pill is active, grid must render Sci-Fi movies! But got: "${renderedTitle}"`
  );
});

args.TargetContent:
await check('SPATIAL', 'Details View Cast Rail Navigation', async function () {
  var h = createHarness({ initialRoute: 'details' });
  h.app.openDetails({ id: 693134, type: 'movie', title: 'Dune: Part Two' });
  await sleep(50);

  var castRail = h.document.getElementById('details-cast-rail');
  assert(castRail, 'Cast rail must exist');
  var castItems = castRail.querySelectorAll('.cast-item');
  assert(castItems.length > 0, 'Cast items must be rendered');

  h.nav.setFocus(castItems[0]);
  assert.strictEqual(h.nav.getCurrentFocus(), castItems[0]);
  assert.strictEqual(castItems[0].getAttribute('data-nav'), 'true');
  assert.strictEqual(castItems[0].getAttribute('data-nav-group'), 'details-cast');
});

